#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-or-later

set -e

trap 'rm -f .tmp-$$' EXIT

name=$(printf %s ${1#*/main} | sed s,/,_,g)
class=$(printf '%s' $name | tr '[:lower:]' '[:upper:]')
pretty=$(printf '%s' $name | tr _ ' ')

sed_cmd_name='s|.*/\([^/]*\).c|'
opt_cmd_name='\tPA_OPT_CMD("\1", v, cmd'$name'_\1, help'$name'_\1)'

cat >.tmp-$$

cat <<EOF
/* Generated by $0 */

#ifndef CMD${class}_TABLE_H
#define CMD${class}_TABLE_H

#include "parse_argv.h"

$(sed $sed_cmd_name'int cmd'$name'_\1(int argc, const char **argv);|' .tmp-$$)
int cmd${name:-_main}(int argc, const char **argv);

$(sed $sed_cmd_name'extern const char *help'$name'_\1;|' .tmp-$$)

#define CMD${class}_TABLE(v) \\
	PA_OPT_GROUP(BUILD_REPO_NAME " -${pretty:- main} commands:"), \\
$(sed -e '$!'$sed_cmd_name"$opt_cmd_name"', \\|' \
      -e '$'$sed_cmd_name"$opt_cmd_name"'|' .tmp-$$)

#endif /* CMD${class}_TABLE_H */
EOF
